parameters.jsCode:
const input = $json;

const clean = (v) => String(v ?? '').trim().replace(/\s+/g, ' ');
const digitsOnly = (v) => String(v ?? '').replace(/\D/g, '');
const parseBudget = (v) => {
  const s = String(v ?? '').toLowerCase().replace(/[,₹\s]/g, '');
  if (!s) return null;
  if (s.endsWith('k')) {
    const n = Number(s.slice(0, -1));
    return Number.isFinite(n) ? Math.round(n * 1000) : null;
  }
  const n = Number(s);
  return Number.isFinite(n) ? Math.round(n) : null;
};

const fromTally = Array.isArray(input.fields) || !!input.formName;

const name = clean(input.name ?? input.Name ?? input.full_name);
const phoneRaw = clean(input.phone ?? input.Phone ?? input.mobile ?? input['Phone Number']);
const email = clean(input.email ?? input.Email);
const serviceNeeded = clean(input.service ?? input.service_needed ?? input['Service needed'] ?? input.serviceType);
const budgetRaw = clean(input.budget ?? input.Budget ?? input['Estimated budget']);
const message = clean(input.message ?? input.Message ?? input.notes ?? input.requirement);

if (!name || !phoneRaw || !serviceNeeded) {
  throw new Error('Missing required fields: name, phone, service_needed');
}

const d = digitsOnly(phoneRaw);
let phoneNormalized = d;
if (d.length === 10) {
  phoneNormalized = `+91${d}`;
} else if (!d.startsWith('91') && d.length > 10) {
  phoneNormalized = `+${d}`;
} else if (d.startsWith('91')) {
  phoneNormalized = `+${d}`;
}

const now = new Date();
const stamp = now.toISOString().replace(/[-:TZ.]/g, '').slice(0, 14);
const rand = Math.random().toString(36).slice(2, 6);

const clientName = clean(input.client_name || $env.DEFAULT_CLIENT_NAME || 'client');
const ownerEmail = clean(input.owner_email || $env.DEFAULT_OWNER_EMAIL || 'owner@example.com');
const source = clean(input.source || (fromTally ? 'tally_form' : 'client_website_form'));
const budgetValue = parseBudget(budgetRaw);

const lead = {
  lead_id: `LC-${stamp}-${rand}`,
  created_at_utc: now.toISOString(),
  source,
  client_name: clientName,
  name,
  phone_raw: phoneRaw,
  phone_normalized: phoneNormalized,
  email: email || '',
  service_needed: serviceNeeded,
  budget_raw: budgetRaw || '',
  budget_value_inr: budgetValue,
  message: message || '',
  status: 'new',
  dedupe_key: `${clientName}:${phoneNormalized}:${serviceNeeded}`,
  owner_email: ownerEmail
};

return [{ json: lead }];

const lead = $json;
const ownerNumber = String($env.DEFAULT_OWNER_WHATSAPP || '').replace(/\D/g, '');
const msg = `Hi ${lead.name}, thanks for your inquiry about ${lead.service_needed}. We'll contact you shortly.`;
const waLink = ownerNumber
  ? `https://wa.me/${ownerNumber}?text=${encodeURIComponent(msg)}`
  : '';

return [{
  json: {
    ...lead,
    whatsapp_link: waLink,
    duplicate_flag: false,
    sla_hours: Number($env.DEFAULT_RESPONSE_SLA_HOURS || 24)
  }
}];

